"""Boss ability runner and per-encounter scripts for WARCRAFT: ATARI (unofficial fan game)."""

import math

from util import clamp, hyp, norm, seg_dist, in_cone
from data import ADDS, GOTHIK_WAVES, KT_WAVES, U

ARENA = (8.0, 16.0, 312.0, 192.0)

# Abilities that never stop the boss from walking or attacking.
PASSIVE = {"trail", "dotall", "summon", "necro", "devour", "aura", "decimate", "doom", "mark", "charm", "wrap"}


# ---------------------------------------------------------------------------
# helpers
# ---------------------------------------------------------------------------
def dmgs(g, e, a, key="dmg"):
    return a.get(key, 0) * g.enemy_dmg_scale() * e.dmg_scale()


def pick_player(g, e):
    if e.target is not None and e.target.alive:
        return e.target
    return g.pick_target(e)


def hit_players(g, t, dmg, elem="phys", status=None, label=None):
    """Telegraph resolve callback: damage every player inside a circle telegraph."""
    for p in g.alive_players():
        if hyp(p.x - t["x"], p.y - t["y"]) <= t["r"] + p.r * 0.5:
            g.hurt_player(p, dmg, None, elem)
            if status and p.alive:
                p.add_status(status[0], status[1], status[2])
    g.sfx("boom")


def announce(g, e, label):
    if label:
        e.cast = label
        g.text(e.x, e.y - e.r - 12, label, "#ff5555")


def living(g, e):
    return e.alive and g.state == "fight"


def count_kind(g, kind):
    return sum(1 for x in g.enemies if x.alive and x.kind == kind)


# ---------------------------------------------------------------------------
# ability handlers: fn(g, e, a) -> True (fired) / False (nothing to do)
# ---------------------------------------------------------------------------
def ab_line(g, e, a):
    tgt = pick_player(g, e)
    if not tgt:
        return False
    dx, dy = norm(tgt.x - e.x, tgt.y - e.y)
    ang = math.atan2(dy, dx)
    ox, oy = e.x, e.y
    length, w = a.get("len", 300), a.get("w", 8)
    dmg = dmgs(g, e, a)
    delay = a.get("delay", 1.2)
    e.busy = delay + 0.1
    announce(g, e, a.get("label"))

    def resolve(g, t):
        if not e.alive:
            return
        bx, by = ox + math.cos(ang) * length, oy + math.sin(ang) * length
        for p in g.alive_players():
            if seg_dist(p.x, p.y, ox, oy, bx, by) <= w / 2 + p.r:
                g.hurt_player(p, dmg, e, "phys")
        g.ev(t="beam", pts=[[round(ox, 1), round(oy, 1)], [round(bx, 1), round(by, 1)]], c="#55ff55")
        g.sfx("boom")
    g.tele("line", delay, resolve, x=ox, y=oy, a=ang, len=length, w=w, c="#55ff55")
    return True


def ab_cone(g, e, a):
    tgt = pick_player(g, e)
    if not tgt:
        return False
    dx, dy = norm(tgt.x - e.x, tgt.y - e.y)
    ang = math.atan2(dy, dx)
    length, arc = a.get("len", 40), a.get("arc", 80)
    delay = a.get("delay", 1.0)
    dmg = dmgs(g, e, a)
    status = a.get("status")
    ox, oy = e.x, e.y
    e.busy = delay + 0.1
    announce(g, e, a.get("label"))

    def resolve(g, t):
        if not e.alive:
            return
        fx, fy = math.cos(ang), math.sin(ang)
        for p in g.alive_players():
            if in_cone(ox, oy, fx, fy, p.x, p.y, p.r, length, math.radians(arc / 2)):
                g.hurt_player(p, dmg, e, "phys")
                if status and p.alive:
                    p.add_status(status[0], status[1], status[2])
        g.sfx("boom")
    g.tele("cone", delay, resolve, x=ox, y=oy, a=ang, arc=arc, len=length)
    return True


def ab_nova(g, e, a):
    delay = a.get("delay", 1.2)
    dmg = dmgs(g, e, a)
    drain = a.get("drain", 0)
    e.busy = delay + 0.1
    announce(g, e, a.get("label"))

    def resolve(g, t):
        if not e.alive:
            return
        for p in g.alive_players():
            if hyp(p.x - e.x, p.y - e.y) <= t["r"] + p.r * 0.5:
                g.hurt_player(p, dmg, e, "phys")
                if drain and p.alive:
                    p.res = max(0.0, p.res - drain)
        g.ev(t="fx", k="nova", x=round(e.x, 1), y=round(e.y, 1), r=a["r"], c="#ff5555")
        g.sfx("boom")
    g.tele("circle", delay, resolve, follow=e, x=e.x, y=e.y, r=a["r"])
    return True


def ab_blink(g, e, a):
    tgt = pick_player(g, e)
    if not tgt:
        return False
    delay = a.get("delay", 1.0)
    dmg = dmgs(g, e, a)
    px, py = tgt.x, tgt.y
    e.busy = delay + 0.1
    announce(g, e, a.get("label"))

    def resolve(g, t):
        if not e.alive:
            return
        e.x, e.y = px, py
        g.constrain(e)
        g.ev(t="fx", k="burst", x=round(e.x, 1), y=round(e.y, 1), r=a["r"], c="#aa55ff")
        hit_players(g, dict(x=e.x, y=e.y, r=a["r"]), dmg, "shadow")
    g.tele("circle", delay, resolve, x=px, y=py, r=a["r"], c="#aa55ff")
    return True


def ab_summon(g, e, a):
    kind = a["kind"]
    if count_kind(g, kind) >= a.get("max", 6):
        return False
    n = min(a.get("n", 2), a.get("max", 6) - count_kind(g, kind))
    for i in range(n):
        ang = g.rng.uniform(0, math.tau)
        g.spawn_add(kind, e.x + math.cos(ang) * (e.r + 10), e.y + math.sin(ang) * (e.r + 10))
    announce(g, e, a.get("label"))
    return True


def ab_volley(g, e, a):
    tgt = pick_player(g, e)
    if not tgt:
        return False
    n, spread = a.get("n", 1), math.radians(a.get("spread", 0))
    dmg = dmgs(g, e, a)
    for i in range(n):
        off = (i - (n - 1) / 2.0) * spread
        g.enemy_shot(e, tgt, dmg, a.get("spd", 95), a.get("elem", "shadow"), a.get("status"), spread=off)
    g.sfx("zap")
    e.busy = max(e.busy, 0.35)
    if a.get("label") and e.boss and a["cd"] > 5:
        announce(g, e, a["label"])
    return True


def ab_ring(g, e, a):
    n = a.get("n", 8)
    dmg = dmgs(g, e, a)
    base = g.rng.uniform(0, math.tau)
    for i in range(n):
        ang = base + i / n * math.tau
        g.projs.append(dict(id=g.nid(), team="enemy", x=e.x, y=e.y, vx=math.cos(ang) * a.get("spd", 70),
                            vy=math.sin(ang) * a.get("spd", 70), r=2.5, dmg=dmg, elem=a.get("elem", "shadow"),
                            life=3.5, src=e, status=None, kind="eshot",
                            color={"frost": "#55ffff", "poison": "#55aa00", "nature": "#55ff55"}.get(a.get("elem"), "#ff55ff"),
                            pierce=False, hit=set()))
    if a.get("spawn") and count_kind(g, a["spawn"]) < 5:
        g.spawn_add(a["spawn"], e.x + g.rng.uniform(-10, 10), e.y + e.r + 6)
    e.busy = max(e.busy, 0.5)
    announce(g, e, a.get("label"))
    return True


def ab_pools(g, e, a):
    alive = g.alive_players()
    if not alive:
        return False
    positions = []
    n = a.get("n", 2)
    for i in range(n):
        if a.get("at") == "mix" and i % 2 == 1:
            positions.append((g.rng.uniform(30, 290), g.rng.uniform(40, 180)))
        else:
            p = alive[i % len(alive)]
            positions.append((p.x + g.rng.uniform(-6, 6), p.y + g.rng.uniform(-6, 6)))
    delay, r = a.get("delay", 1.0), a["r"]
    elem = a.get("elem", "fire")
    col = {"fire": "#ff8800", "frost": "#55ffff", "shadow": "#aa00aa", "poison": "#55aa00"}.get(elem, "#ff8800")
    boom = a.get("boom")
    dmg = dmgs(g, e, a, "boom") if boom else 0
    per_tick = a.get("dps", 0) * 1.2
    for (px, py) in positions:
        def resolve(g, t, px=px, py=py):
            if boom:
                g.ev(t="fx", k="burst", x=round(px, 1), y=round(py, 1), r=r, c=col)
                hit_players(g, dict(x=px, y=py, r=r), dmg, elem)
            else:
                g.add_zone("pool", "enemy", px, py, r, a.get("dur", 6), interval=0.5, dmg=per_tick,
                           slow=a.get("slow", 0.0), color=col)
        g.tele("circle", delay, resolve, x=px, y=py, r=r, c=col)
    announce(g, e, a.get("label"))
    return True


def ab_aura(g, e, a):
    g.add_zone("pool", "enemy", e.x, e.y, a["r"], a.get("dur", 8), interval=0.5, dmg=a.get("dmg", 4), follow=e,
               color="#55ff55")
    announce(g, e, a.get("label"))
    return True


def ab_trail(g, e, a):
    g.add_zone("pool", "enemy", e.x, e.y, a["r"], a.get("dur", 8), interval=0.5, dmg=a.get("dps", 2) * 1.2,
               color="#55ff55")
    return True


def ab_dotall(g, e, a):
    for p in g.alive_players():
        p.add_dot(dmgs(g, e, a, "dps") * 2.0, a.get("dur", 6), a.get("elem", "shadow"), e, tag="curse_" + (a.get("label") or "x"))
    if not a.get("silent"):
        announce(g, e, a.get("label"))
        g.sfx("zap")
    return True


def ab_necro(g, e, a):
    g.necro_t = a.get("dur", 8)
    announce(g, e, a.get("label"))
    g.log("Healing is blocked for %ds!" % a.get("dur", 8), "#aa00aa")
    return True


def ab_doom(g, e, a):
    if g.doom:
        return False
    g.doom = dict(t=a.get("delay", 12), pct=a.get("pct", 0.35))
    announce(g, e, a.get("label"))
    g.log("INEVITABLE DOOM in %ds! Shield or avoid it." % a.get("delay", 12), "#aa00aa")
    return True


def ab_mark(g, e, a):
    alive = g.alive_players()
    if not alive:
        return False
    tgt = g.rng.choice(alive)
    delay, r = a.get("delay", 3.5), a["r"]
    dmg = dmgs(g, e, a)
    drain = a.get("drain", 0)
    pool = a.get("pool")

    def resolve(g, t):
        if not e.alive:
            return
        for p in g.alive_players():
            if hyp(p.x - t["x"], p.y - t["y"]) <= t["r"] + p.r * 0.5:
                g.hurt_player(p, dmg, e, "shadow")
                if drain and p.alive:
                    p.res = max(0.0, p.res - drain)
        g.ev(t="fx", k="burst", x=round(t["x"], 1), y=round(t["y"], 1), r=t["r"], c="#ff55ff")
        g.sfx("boom")
        if pool:
            g.add_zone("pool", "enemy", t["x"], t["y"], 16, 7, interval=0.5, dmg=3.0, color="#55ff55")
    g.tele("circle", delay, resolve, follow=tgt, x=tgt.x, y=tgt.y, r=r, c="#ff55ff")
    g.text(tgt.x, tgt.y - 12, "MARKED - RUN!", "#ff55ff")
    announce(g, e, a.get("label"))
    return True


def ab_wrap(g, e, a):
    alive = [p for p in g.alive_players() if not p.has("wrapped")]
    if not alive:
        return False
    tgt = g.rng.choice(alive)
    dur = a.get("dur", 8) if len(g.joined()) >= 2 else 4
    tgt.add_status("stun", dur)
    tgt.add_status("wrapped", dur)
    cocoon = g.spawn_add("wrap", tgt.x, tgt.y)
    cocoon.link = tgt
    cocoon.hp = cocoon.maxhp = 40.0 + 12 * g.enc_idx

    def expire():
        if cocoon.alive:
            cocoon.alive = False
            g.text(cocoon.x, cocoon.y - 8, "COCOON BURSTS", "#aaaaaa")
    g.later(dur, expire)
    announce(g, e, a.get("label"))
    g.log("P%d is wrapped! Free them!" % (tgt.pid + 1), "#ff5555")
    return True


def ab_decimate(g, e, a):
    delay = 1.4
    announce(g, e, a.get("label"))
    pct = a.get("pct", 0.4)

    def resolve(g, t):
        if not e.alive:
            return
        for p in g.alive_players():
            g.hurt_player(p, p.hp * pct, e, "shadow")
        for x in g.enemies:
            if x.alive and x.kind == "chow":
                x.hp = max(1.0, x.maxhp * 0.05)
        g.ev(t="fx", k="nova", x=160, y=100, r=200, c="#aa0000")
        g.sfx("boom")
    g.tele("flash", delay, resolve, c="#aa0000")
    return True


def ab_devour(g, e, a):
    for x in g.enemies:
        if x.alive and x.kind == "chow" and hyp(x.x - e.x, x.y - e.y) <= a.get("r", 34) + x.r:
            x.alive = False
            e.hp = min(e.maxhp, e.hp + e.maxhp * a.get("heal", 0.04))
            g.text(e.x, e.y - e.r - 8, "DEVOUR", "#aa0000")
            g.ev(t="fx", k="burst", x=round(x.x, 1), y=round(x.y, 1), r=8, c="#aa0000")
            return True
    return False


def ab_breath(g, e, a):
    delay = a.get("delay", 3.4)
    pct = a.get("pct", 0.55)
    blocks = []
    for i in range(a.get("blocks", 2)):
        for _ in range(12):
            bx, by = g.rng.uniform(40, 270), g.rng.uniform(80, 160)
            ok = all(abs(bx - r[0]) > 24 or abs(by - r[1]) > 24 for r in g.obstacles)
            if ok:
                break
        rect = (bx, by, 16.0, 16.0)
        g.obstacles.append(rect)
        blocks.append(rect)
    ox, oy = e.x, e.y
    e.busy = delay + 0.2
    announce(g, e, a.get("label"))
    g.log("Hide behind an ice block!", "#55ffff")

    def covered(px, py):
        d = hyp(px - ox, py - oy)
        steps = max(2, int(d / 3))
        for i in range(1, steps):
            x = ox + (px - ox) * i / steps
            y = oy + (py - oy) * i / steps
            for (rx, ry, rw, rh) in g.obstacles:
                if rx - 1 <= x <= rx + rw + 1 and ry - 1 <= y <= ry + rh + 1:
                    return True
        return False

    def resolve(g, t):
        for p in g.alive_players():
            if not covered(p.x, p.y):
                g.hurt_player(p, p.maxhp * pct, e, "frost")
                g.text(p.x, p.y - 12, "FROZEN", "#55ffff")
        for rect in blocks:
            if rect in g.obstacles:
                g.obstacles.remove(rect)
        g.ev(t="fx", k="nova", x=160, y=100, r=210, c="#55ffff")
        g.sfx("freeze")
    g.tele("flash", delay, resolve, c="#55ffff")
    return True


def ab_charm(g, e, a):
    alive = g.alive_players()
    if not alive:
        return False
    tgt = g.rng.choice(alive)
    tgt.add_status("charm", a.get("dur", 5))
    g.text(tgt.x, tgt.y - 12, "CHARMED", "#aa55ff")
    announce(g, e, a.get("label"))
    return True


def ab_charge(g, e, a):
    tgt = pick_player(g, e)
    if not tgt:
        return False
    dx, dy = norm(tgt.x - e.x, tgt.y - e.y)
    ang = math.atan2(dy, dx)
    delay, w = a.get("delay", 1.0), a.get("w", 10)
    dmg = dmgs(g, e, a)
    ox, oy = e.x, e.y
    e.busy = delay + 0.1
    announce(g, e, a.get("label"))

    def resolve(g, t):
        if not e.alive:
            return
        e.charging = dict(dx=dx, dy=dy, t=0.6, w=w, dmg=dmg, hit=set(), spd=a.get("spd", 190))
    g.tele("line", delay, resolve, x=ox, y=oy, a=ang, len=a.get("spd", 190) * 0.6, w=w, c="#ffaa00")
    return True


def ab_eruption(g, e, a):
    cols = a.get("cols", 5)
    s = getattr(e, "safe_col", None)
    if s is None:
        s = g.rng.randrange(cols)
        e.safe_dir = 1
    else:
        step = e.safe_dir if g.rng.random() < 0.75 else -e.safe_dir
        s2 = s + step
        if s2 < 0 or s2 >= cols:
            e.safe_dir = -e.safe_dir
            s2 = s + e.safe_dir
        else:
            e.safe_dir = step
        s = clamp(s2, 0, cols - 1)
    e.safe_col = s
    delay = a.get("delay", 1.15)
    dmg = dmgs(g, e, a)
    x0, x1 = ARENA[0], ARENA[2]
    cw = (x1 - x0) / cols

    def resolve(g, t, s=s):
        for p in g.alive_players():
            col = int(clamp((p.x - x0) // cw, 0, cols - 1))
            if col != s:
                g.hurt_player(p, dmg, e, "fire")
        g.ev(t="fx", k="nova", x=160, y=110, r=190, c="#ff8800")
        g.sfx("boom")
    g.tele("cols", delay, resolve, cols=cols, safe=s, c="#ff8800")
    e.cast = a.get("label")
    return True


HANDLERS = {
    "line": ab_line, "cone": ab_cone, "nova": ab_nova, "blink": ab_blink, "summon": ab_summon, "volley": ab_volley,
    "ring": ab_ring, "pools": ab_pools, "aura": ab_aura, "trail": ab_trail, "dotall": ab_dotall, "necro": ab_necro,
    "doom": ab_doom, "mark": ab_mark, "wrap": ab_wrap, "decimate": ab_decimate, "devour": ab_devour,
    "breath": ab_breath, "charm": ab_charm, "charge": ab_charge, "eruption": ab_eruption,
}


def run_abilities(g, e, dt):
    for slot in e.abil:
        if slot["t"] > 0:
            continue
        a = slot["a"]
        ph = a.get("phase")
        if ph and not (ph[0] <= g.phase <= ph[1]):
            slot["t"] = 0.5
            continue
        k = a["k"]
        if k not in PASSIVE and e.busy > 0:
            continue
        fn = HANDLERS.get(k)
        if not fn:
            slot["t"] = 99
            continue
        fired = fn(g, e, a)
        slot["t"] = (a.get("interval", a["cd"]) if k == "eruption" else a["cd"]) if fired else 1.0
        if fired and k not in PASSIVE and e.busy > 0:
            break


def update_charge(g, e, dt):
    c = e.charging
    step = c["spd"] * dt
    ox, oy = e.x, e.y
    e.x += c["dx"] * step
    e.y += c["dy"] * step
    g.constrain(e)
    for p in g.alive_players():
        if id(p) not in c["hit"] and hyp(p.x - e.x, p.y - e.y) <= e.r + p.r + c["w"] / 2:
            c["hit"].add(id(p))
            g.hurt_player(p, c["dmg"], e, "phys")
            p.add_status("stun", 1.0)
    c["t"] -= dt
    if c["t"] <= 0 or hyp(e.x - ox, e.y - oy) < step * 0.3:
        e.charging = None
        e.atk_t = 1.0


def update_global(g, dt):
    if g.doom:
        g.doom["t"] -= dt
        if g.doom["t"] <= 0:
            pct = g.doom["pct"]
            g.doom = None
            for p in g.alive_players():
                g.hurt_player(p, p.maxhp * pct, None, "shadow")
            g.ev(t="fx", k="nova", x=160, y=100, r=200, c="#aa00aa")
            g.sfx("boom")
            g.log("Inevitable Doom strikes!", "#aa00aa")


# ---------------------------------------------------------------------------
# Encounter scripts
# ---------------------------------------------------------------------------
class Script:
    def on_start(self, g):
        pass

    def on_tick(self, g, dt):
        pass

    def on_damage(self, g, e):
        pass

    def on_death(self, g, e):
        pass

    @staticmethod
    def main_boss(g):
        for e in g.enemies:
            if e.alive and e.boss:
                return e
        return None


class FaerlinaScript(Script):
    def on_start(self, g):
        g.sstate["et"] = 22.0

    def on_tick(self, g, dt):
        s = g.sstate
        boss = self.main_boss(g)
        if not boss:
            return
        s["et"] -= dt
        if s["et"] <= 0 and boss.enrage_t <= 0:
            boss.enrage_mult = 1.6
            boss.enrage_t = 14.0
            s["et"] = 30.0
            g.log("Faerlina ENRAGES! Kill a Worshipper to silence her!", "#ff5555")
            g.banner("ENRAGE! KILL A WORSHIPPER", 2.0)
        if boss.enrage_t > 0:
            s["info"] = "ENRAGED! KILL A WORSHIPPER"
        else:
            s["info"] = "ENRAGE IN %ds" % max(0, int(s["et"]))

    def on_death(self, g, e):
        boss = self.main_boss(g)
        if e.kind == "worshipper" and boss and boss.enrage_t > 0:
            boss.enrage_t = 0
            g.sstate["et"] = max(g.sstate.get("et", 0), 24.0)
            g.log("A Worshipper is slain. The enrage fades.", "#55ff55")
            g.text(boss.x, boss.y - 14, "SILENCED", "#55ff55")


class WaveScript(Script):
    """Gothik and Kel'Thuzad: boss is untargetable while waves of adds pour in."""

    def __init__(self, waves, kt=False):
        self.waves = waves
        self.kt = kt

    def on_start(self, g):
        boss = self.main_boss(g)
        boss.gated = True
        g.sstate.update(wave=0, wt=1.5, info="WAVES 0/%d" % len(self.waves))
        g.phase = 1

    def spawn_wave(self, g, idx):
        spots = [(24, 36), (296, 36), (24, 110), (296, 110), (160, 28)]
        i = 0
        for kind, n in self.waves[idx]:
            for _ in range(n):
                sx, sy = spots[i % len(spots)]
                i += 1
                g.spawn_add(kind, sx + g.rng.uniform(-10, 10), sy + g.rng.uniform(-8, 8))
        g.log("Wave %d/%d arrives!" % (idx + 1, len(self.waves)), "#ff55ff")
        g.banner("WAVE %d / %d" % (idx + 1, len(self.waves)), 1.5)
        g.sfx("boom")

    def on_tick(self, g, dt):
        s = g.sstate
        boss = self.main_boss(g)
        if not boss:
            return
        adds = any(x.alive and not x.boss for x in g.enemies)
        if boss.gated:
            s["wt"] -= dt
            n = len(self.waves)
            if s["wave"] < n:
                if s["wt"] <= 0 or (not adds and s["wave"] > 0 and s["wt"] < 11):
                    self.spawn_wave(g, s["wave"])
                    s["wave"] += 1
                    s["wt"] = 15.0
                s["info"] = "WAVE %d/%d - SURVIVE" % (s["wave"], n)
            elif not adds:
                boss.gated = False
                g.phase = 2
                nm = "KEL'THUZAD" if self.kt else "GOTHIK"
                g.banner("%s ENGAGES!" % nm, 2.2)
                g.log("%s is now vulnerable!" % boss.name, "#ff55ff")
                if self.kt:
                    for a in boss.abil:
                        a["t"] = max(a["t"], 2.5)
            else:
                s["info"] = "CLEAR THE ADDS"
        else:
            if self.kt:
                s["info"] = "PHASE %d" % g.phase
            else:
                s["info"] = "KILL GOTHIK"

    def on_damage(self, g, e):
        if self.kt and e.boss and g.phase == 2 and e.hp / e.maxhp < 0.4:
            g.phase = 3
            g.banner("MASTER, I REQUIRE AID!", 2.4)
            g.log("Kel'Thuzad summons Guardians of Icecrown!", "#55ffff")
