effects.py:
"""Item effects (procs). An item may carry one effect: a dict like
    {"type": "chain", "elem": "nature", "chance": 0.18, "targets": 4, "coef": 0.9, "label": "THUNDERFURY"}
`type` picks an entry of EFFECTS below; the other keys are that effect's parameters. To add a brand new
effect type, write a small class here and register it with @register("yourtype"); then use it from
custom_items.json. Effects only ever fire from damage the item's owner deals, and the damage they cause
never triggers effects itself.
"""
import math

ELEM_COLOR = {"fire": "#ff8800", "frost": "#55ffff", "shadow": "#ff55ff", "nature": "#55ff55",
              "holy": "#ffff55", "poison": "#55aa00", "phys": "#ffffff", "arcane": "#aa55ff", "lightning": "#55aaff"}
ELEM_BEAM = {"nature": "#55aaff", "lightning": "#55aaff"}

EFFECTS = {}


def register(name):
    def deco(cls):
        EFFECTS[name] = cls()
        return cls
    return deco


def _pct(x):
    return ("%g" % round(x * 100, 1)) + "%"


def _proc_hit(g, p, target, base, elem):
    g.in_proc = True
    try:
        return g.hit_enemy(target, base, p, elem, crit=False)
    finally:
        g.in_proc = False


class Effect:
    def describe(self, eff):
        return ""

    def on_hit(self, g, p, e, eff, ctx):
        """Called after the owner damaged enemy e. ctx: dict(base, amt, dot, elem)."""

    def on_update(self, g, p, eff, dt):
        pass


@register("chain")
class Chain(Effect):
    """Chance on hit: an arc of damage jumps between up to `targets` nearby enemies."""

    def describe(self, eff):
        el = eff.get("elem", "nature")
        return "Chance on hit from any spell (%s): %s hits up to %d enemies." % (
            _pct(eff.get("chance", 0.15)), "Chain Lightning" if el in ("nature", "lightning") else "a chain of %s" % el, int(eff.get("targets", 4)))

    def on_hit(self, g, p, e, eff, ctx):
        if ctx["dot"] or g.rng.random() >= eff.get("chance", 0.15):
            return
        rng_, n = float(eff.get("range", 70)), int(eff.get("targets", 4))
        chain, cur = [e], e
        while len(chain) < n:
            nxt, bd = None, rng_
            for o in g.enemies:
                if o.alive and o not in chain and not o.gated:
                    d = math.hypot(o.x - cur.x, o.y - cur.y)
                    if d < bd:
                        nxt, bd = o, d
            if nxt is None:
                break
            chain.append(nxt)
            cur = nxt
        base = max(ctx["base"] * float(eff.get("coef", 0.9)), float(eff.get("flat", 6)))
        elem = eff.get("elem", "nature")
        color = ELEM_BEAM.get(elem, ELEM_COLOR.get(elem, "#55aaff"))
        prev = (p.x, p.y - 4)
        for t in chain:
            g.ev(t="beam", pts=[[round(prev[0], 1), round(prev[1], 1)], [round(t.x, 1), round(t.y, 1)]], c=color)
            prev = (t.x, t.y)
        for t in chain:
            _proc_hit(g, p, t, base, elem)
        if eff.get("label"):
            g.text(p.x, p.y - 16, eff["label"], color)
        g.sfx("zap" if False else "kill")


@register("nova")
class Nova(Effect):
    """Chance on hit: a nova centred on the owner damages every enemy within `radius`."""

    def describe(self, eff):
        return "Chance on hit from any spell (%s): %s nova around you." % (_pct(eff.get("chance", 0.15)), eff.get("elem", "fire").capitalize())

    def on_hit(self, g, p, e, eff, ctx):
        if ctx["dot"] or g.rng.random() >= eff.get("chance", 0.15):
            return
        r = float(eff.get("radius", 46))
        elem = eff.get("elem", "fire")
        color = ELEM_COLOR.get(elem, "#ff8800")
        g.ev(t="fx", k="nova", x=round(p.x, 1), y=round(p.y, 1), r=r, c=color)
        base = max(ctx["base"] * float(eff.get("coef", 0.8)), float(eff.get("flat", 6)))
        for t in list(g.enemies):
            if t.alive and not t.gated and math.hypot(t.x - p.x, t.y - p.y) <= r + t.r:
                _proc_hit(g, p, t, base, elem)
        if eff.get("label"):
            g.text(p.x, p.y - 16, eff["label"], color)
        g.sfx("boom")


@register("soul_siphon")
class SoulSiphon(Effect):
    """Any damage can siphon a soul: drains a % of the enemy's health and adds a stack (max `stacks`).
    At full stacks the stacks are consumed for `duration` seconds of extra damage, haste and health regen."""

    def describe(self, eff):
        return ("Every damage has a chance (%s) to siphon a soul, draining %s of the enemy's health. At %d souls: for %gs gain "
                "+%s damage, +%s haste and %s of your max health regenerated." % (
                    _pct(eff.get("chance", 0.12)), _pct(eff.get("drain", 0.02)), int(eff.get("stacks", 10)), eff.get("duration", 8),
                    _pct(eff.get("dmg", 0.2)), _pct(eff.get("haste", 0.2)), _pct(eff.get("regen", 1.0))))

    def on_hit(self, g, p, e, eff, ctx):
        chance = eff.get("chance", 0.12) * (float(eff.get("dot_factor", 0.35)) if ctx["dot"] else 1.0)
        if g.rng.random() >= chance or not e.alive:
            return
        drain = float(eff.get("drain", 0.02)) * (float(eff.get("boss_factor", 0.5)) if e.boss else 1.0)
        amt = e.maxhp * drain
        e.hp -= amt
        g.ev(t="fx", k="burst", x=round(e.x, 1), y=round(e.y, 1), r=5, c="#55ffff")
        g.ev(t="beam", pts=[[round(e.x, 1), round(e.y, 1)], [round(p.x, 1), round(p.y - 4, 1)]], c="#55ffff")
        g.ev(t="dmg", x=round(e.x, 1), y=round(e.y - e.r - 2, 1), v=int(round(amt)), c="#55ffff", crit=False)
        if e.hp <= 0:
            g.kill_enemy(e, p)
        cap = int(eff.get("stacks", 10))
        p.add_stack("souls", 25.0, cap)
        if p.sval("souls") >= cap:
            p.clear_status("souls")
            dur = float(eff.get("duration", 8))
            p.st["soulreap"] = [dur, 1.0]
            p.soul = dict(dmg=float(eff.get("dmg", 0.2)), haste=float(eff.get("haste", 0.2)), regen=float(eff.get("regen", 1.0)), dur=dur)
            g.text(p.x, p.y - 18, "SOULS HARVESTED!", "#55ffff")
            g.log("%s harvests %d souls!" % ("P%d" % (p.pid + 1), cap), "#55ffff")
            g.sfx("boom")

    def on_update(self, g, p, eff, dt):
        if p.has("soulreap") and getattr(p, "soul", None) and p.alive:
            g.heal(p, p.maxhp * p.soul["regen"] / p.soul["dur"] * dt, p, quiet=True)


@register("heal_proc")
class HealProc(Effect):
    """Example custom effect: chance on hit to heal the owner for `amount` percent of max health."""

    def describe(self, eff):
        return "Chance on hit (%s): heal %s of your max health." % (_pct(eff.get("chance", 0.05)), _pct(eff.get("amount", 0.05)))

    def on_hit(self, g, p, e, eff, ctx):
        if ctx["dot"] or g.rng.random() >= eff.get("chance", 0.05):
            return
        g.heal(p, p.maxhp * float(eff.get("amount", 0.05)), p, quiet=False)


def describe(eff):
    h = EFFECTS.get((eff or {}).get("type"))
    return h.describe(eff) if h else ""


def valid(eff):
    return isinstance(eff, dict) and eff.get("type") in EFFECTS

progression.py:
"""Character levels, XP and per-level stat gains."""

MAX_LEVEL = 10
# cumulative XP needed to REACH each level (index 0 = level 1)
XP_TABLE = [0, 150, 400, 800, 1400, 2200, 3400, 5000, 7200, 10000]
HP_PER_LEVEL = 0.05     # +5% max health per level above 1
DMG_PER_LEVEL = 0.03    # +3% damage per level above 1
ENEMY_HP_PER_LEVEL = 0.06   # raids toughen with the party's average level so a level 10 is not a free ride
ENEMY_DMG_PER_LEVEL = 0.03


def level_for_xp(xp):
    lvl = 1
    for i, need in enumerate(XP_TABLE):
        if xp >= need:
            lvl = i + 1
    return min(lvl, MAX_LEVEL)


def xp_into_level(xp):
    """(xp earned inside the current level, xp needed for the next level or None at max)."""
    lvl = level_for_xp(xp)
    if lvl >= MAX_LEVEL:
        return xp - XP_TABLE[-1], None
    return xp - XP_TABLE[lvl - 1], XP_TABLE[lvl] - XP_TABLE[lvl - 1]


def talent_points(level):
    return max(0, level - 1)


def boss_xp(raid, idx):
    return int(raid["xp_base"] + raid["xp_step"] * idx)

saves.py:
"""Character saves. A browser keeps a random profile key; the server stores that profile's characters in saves.json.
There are no accounts: the key is the only thing that identifies a profile (copy it to move to another device)."""
import json
import os
import re
import threading
import time

import progression
import talents as tal
from data import CLASSES

MAX_CHARS = 8
KEY_RE = re.compile(r"^[A-Za-z0-9_-]{16,64}$")


def clean_char_name(raw):
    s = "".join(ch for ch in str(raw or "") if ch.isprintable() and ch not in "<>&\"'`")
    return " ".join(s.split())[:12]


class SaveStore:
    def __init__(self, path):
        self.path = path
        self.lock = threading.RLock()
        self.data = {}
        try:
            with open(path, "r") as f:
                d = json.load(f)
            if isinstance(d, dict):
                self.data = d
        except Exception:
            pass

    def _flush(self):
        try:
            tmp = self.path + ".tmp"
            with open(tmp, "w") as f:
                json.dump(self.data, f)
            os.replace(tmp, self.path)
        except OSError:
            pass

    def _chars(self, pk):
        return self.data.setdefault(pk, dict(chars=[]))["chars"]

    @staticmethod
    def view(c):
        lvl = progression.level_for_xp(c["xp"])
        into, need = progression.xp_into_level(c["xp"])
        spent = tal.total_spent(c["talents"])
        return dict(id=c["id"], name=c["name"], cls=c["cls"], xp=c["xp"], level=lvl, into=into, need=need,
                    talents=dict(c["talents"]), points=progression.talent_points(lvl) - spent,
                    runs=c.get("runs", 0), bosses=c.get("bosses", 0), clears=c.get("clears", 0))

    def list(self, pk):
        with self.lock:
            return [self.view(c) for c in self._chars(pk)]

    def get(self, pk, cid):
        with self.lock:
            for c in self._chars(pk):
                if c["id"] == cid:
                    return c
        return None

    def create(self, pk, name, cls):
        name = clean_char_name(name)
        if cls not in CLASSES:
            return None, "UNKNOWN CLASS"
        with self.lock:
            chars = self._chars(pk)
            if len(chars) >= MAX_CHARS:
                return None, "ALL %d SAVE SLOTS ARE FULL" % MAX_CHARS
            if not name:
                name = CLASSES[cls]["name"].upper()
            cid = "c%d%03d" % (int(time.time()), len(chars))
            while any(c["id"] == cid for c in chars):
                cid += "x"
            c = dict(id=cid, name=name, cls=cls, xp=0, talents={}, runs=0, bosses=0, clears=0, created=int(time.time()))
            chars.append(c)
            self._flush()
            return self.view(c), ""

    def delete(self, pk, cid):
        with self.lock:
            chars = self._chars(pk)
            n = len(chars)
            chars[:] = [c for c in chars if c["id"] != cid]
            if len(chars) != n:
                self._flush()
                return True
        return False

    def rename(self, pk, cid, name):
        name = clean_char_name(name)
        with self.lock:
            c = self.get(pk, cid)
            if not c or not name:
                return False
            c["name"] = name
            self._flush()
            return True

    def learn(self, pk, cid, tid):
        with self.lock:
            c = self.get(pk, cid)
            if not c:
                return None, "NO SUCH CHARACTER"
            lvl = progression.level_for_xp(c["xp"])
            avail = progression.talent_points(lvl) - tal.total_spent(c["talents"])
            ok, why = tal.can_learn(c["cls"], c["talents"], tid, avail)
            if not ok:
                return None, why.upper()
            c["talents"][tid] = c["talents"].get(tid, 0) + 1
            self._flush()
            return self.view(c), ""

    def respec(self, pk, cid):
        with self.lock:
            c = self.get(pk, cid)
            if not c:
                return None
            c["talents"] = {}
            self._flush()
            return self.view(c)

    def award(self, pk, cid, xp, boss=False, clear=False, run=False):
        """Add XP. Returns (old_level, new_level, view) or None."""
        with self.lock:
            c = self.get(pk, cid)
            if not c:
                return None
            old = progression.level_for_xp(c["xp"])
            c["xp"] = min(c["xp"] + int(xp), progression.XP_TABLE[-1] + 10 ** 6)
            if boss:
                c["bosses"] = c.get("bosses", 0) + 1
            if clear:
                c["clears"] = c.get("clears", 0) + 1
            if run:
                c["runs"] = c.get("runs", 0) + 1
            self._flush()
            return old, progression.level_for_xp(c["xp"]), self.view(c)

server.py:
#!/usr/bin/env python3
"""WARCRAFT: ATARI (unofficial fan game): web server with rooms, matchmaking, chat and a leaderboard.

Standard library only. Run:  python3 server.py [--host 0.0.0.0] [--port 8000]
Then open http://localhost:8000. Every browser page is its own session. Create a game and share
the 4-letter code, join with a code, or hit QUICK MATCH to be paired with a random player.
"""

import argparse
import json
import os
import queue
import random
import re
import socket
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs

from engine import Game, TICK_RATE
from data import CLASSES, CLASS_ORDER, RESOURCES, BOSSES, WINGS, AFFIXES, CONSUMABLES, RAIDS, RAID_ORDER
import progression
import talents as talents_mod
from saves import SaveStore, KEY_RE

ROOT = os.path.dirname(os.path.abspath(__file__))
STATIC = os.path.join(ROOT, "static")
CORS_ORIGIN = os.environ.get("NAXX_CORS", "")   # set with --cors; "*" allows any site
DATA = os.environ.get("NAXX_DATA") or ROOT   # where scores.json and saves.json live
SCORES = os.path.join(DATA, "scores.json")
SAVES = os.path.join(DATA, "saves.json")

HELD_TTL = 1.2         # seconds a held direction stays active without a refresh from the browser
GRACE = 45.0           # seconds a disconnected browser keeps its seat (phone locked, wifi blip)
MATCH_STALE = 8.0      # a matchmaking ticket that is not polled for this long is dropped
EMPTY_ROOM_TTL = 90.0  # rooms nobody is connected to are deleted after this
MAX_ROOMS = 300
CODE_ALPHA = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"   # no I, O, 0, 1
MAX_SCORES = 200

MIME = {".html": "text/html; charset=utf-8", ".js": "application/javascript; charset=utf-8",
        ".css": "text/css; charset=utf-8", ".json": "application/json", ".png": "image/png",
        ".svg": "image/svg+xml", ".webmanifest": "application/manifest+json", ".ico": "image/x-icon"}

SID_RE = re.compile(r"^[A-Za-z0-9_-]{8,64}$")


def clean_name(raw):
    s = "".join(ch for ch in str(raw or "") if ch.isprintable() and ch not in "<>&\"'`")
    return " ".join(s.split())[:12]


def clean_text(raw):
    s = "".join(ch for ch in str(raw or "") if ch.isprintable())
    return " ".join(s.split())[:120]


def sse(event, obj):
    head = "event: %s\n" % event if event else ""
    return (head + "data: " + json.dumps(obj, separators=(",", ":")) + "\n\n").encode()


class Room:
    """One game: its own Game object, seats, clients and chat."""

    def __init__(self, hub, code):
        self.hub = hub
        self.code = code
        self.lock = threading.Lock()
        self.game = Game()
        self.game.scores = hub.scores
        self.game.on_run_end = self.record_score
        self.game.on_xp = self.award_xp
        self.pks = [None, None]           # profile key behind each seat's saved character
        self.clients = {}                 # queue -> sid
        self.seats = [None, None]         # sid per seat
        self.names = ["", ""]
        self.local = False
        self.chat = []
        self.chat_n = 0
        self.last_chat = {}
        now = time.monotonic()
        self.last_in = [now, now]
        self.auto_paused = False
        self.empty_since = now
        for p in self.game.players:
            p.joined = False

    # ---- seats ---------------------------------------------------------
    def sids(self):
        return [s for s in set(self.seats) if s]

    def my_seats(self, sid):
        return [i for i in (0, 1) if self.seats[i] == sid]

    def sit(self, sid, name, local=False):
        """Caller holds room.lock. Returns the seats given, or None if full."""
        if local:
            if self.seats[0] or self.seats[1]:
                return None
            self.seats = [sid, sid]
            self.names = [name, (name + " 2")[:12]]
            self.local = True
        else:
            free = [i for i in (0, 1) if not self.seats[i]]
            if not free:
                return None
            i = free[0]
            self.seats[i] = sid
            self.names[i] = name
        for i in self.my_seats(sid):
            pl = self.game.players[i]
            # local co-op starts solo; the second player is added from the menu (ADD PLAYER 2)
            pl.joined = not (local and i == 1)
            pl.ready = False
        return self.my_seats(sid)

    def unsit(self, sid):
        """Caller holds room.lock. Frees the sid's seats; returns a seat migration {sid: seat} if any."""
        g = self.game
        for i in self.my_seats(sid):
            self.seats[i] = None
            self.names[i] = ""
            self.pks[i] = None
            g.players[i].joined = False
            g.players[i].ready = False
            g.players[i].char = None
            g.players[i].load_char()
        self.local = False
        moves = {}
        # keep the lone remaining player in seat 0 while still in the menu
        if g.state == "menu" and self.seats[0] is None and self.seats[1] is not None:
            other = self.seats[1]
            p0, p1 = g.players
            p0.sel, p0.joined, p0.ready = p1.sel, True, False
            p0.char = p1.char
            p0.load_char()
            p1.char = None
            p1.load_char()
            self.pks = [self.pks[1], None]
            p1.joined = p1.ready = False
            self.seats = [other, None]
            self.names = [self.names[1], ""]
            moves[other] = 0
        if g.state != "menu" and not any(p.joined for p in g.players):
            g.to_menu()
        return moves

    # ---- chat ----------------------------------------------------------
    def add_chat(self, seat, name, text, sys=False):
        self.chat_n += 1
        m = dict(n=self.chat_n, t=int(time.time()), seat=seat, name=name, text=text, sys=sys)
        self.chat.append(m)
        del self.chat[:-60]
        self.broadcast(sse("chat", m))

    def broadcast(self, payload):
        for q in list(self.clients):
            try:
                q.put_nowait(payload)
            except queue.Full:
                try:
                    q.get_nowait()
                    q.put_nowait(payload)
                except Exception:
                    pass

    # ---- game loop -----------------------------------------------------
    def expire_held(self):
        now = time.monotonic()
        for pid in (0, 1):
            inp = self.game.inp[pid]
            if inp["held"] and now - self.last_in[pid] > HELD_TTL:
                inp["held"] = set()

    def step(self):
        with self.lock:
            if not self.clients:
                return
            self.expire_held()
            try:
                self.game.tick()
                snap = self.game.snapshot()
            except Exception as ex:  # keep the server alive; report and reset the run
                print("tick error in room %s:" % self.code, repr(ex))
                import traceback
                traceback.print_exc()
                self.game.to_menu()
                snap = self.game.snapshot()
            snap["room"] = dict(code=self.code, names=list(self.names), local=self.local,
                                conn=[self.connected(i) for i in (0, 1)])
            payload = sse(None, snap)
        self.broadcast(payload)

    def connected(self, seat):
        sid = self.seats[seat]
        return bool(sid) and sid in self.clients.values()

    def check_hold(self):
        """Pause while a seated player is disconnected; resume when they are all back."""
        with self.lock:
            g = self.game
            missing = any(self.seats[i] and not self.connected(i) for i in (0, 1))
            if missing and not g.paused and g.state in ("fight", "intro", "loot") and self.clients:
                g.paused = True
                self.auto_paused = True
            elif not missing and self.auto_paused:
                self.auto_paused = False
                g.paused = False

    # ---- input / commands ---------------------------------------------
    def apply(self, sid, msg):
        with self.lock:
            mine = self.my_seats(sid)
            if not mine:
                return
            for it in msg.get("inputs") or []:
                try:
                    pid = int(it.get("p"))
                except (TypeError, ValueError, AttributeError):
                    continue
                if pid not in mine:
                    continue
                self.last_in[pid] = time.monotonic()
                held = it.get("held") or []
                press = it.get("press") or []
                if isinstance(held, list) and isinstance(press, list):
                    self.game.set_input(pid, held[:8], press[:12])
            cmd = msg.get("cmd")
            if cmd and isinstance(cmd, dict) and isinstance(cmd.get("name"), str):
                name, data = cmd["name"], cmd.get("data") or {}
                if name in ("pick", "ready", "char"):
                    if data.get("p") not in mine:
                        return
                if name == "raid" and 0 not in mine:
                    return   # only the host (seat 0) chooses the raid
                if name == "char":
                    self.pick_char(data.get("p"), str(msg.get("pk") or ""), str(data.get("id") or ""))
                    return
                if name == "leave" and not self.local:
                    return
                self.game.cmd(name, data)

    # ---- characters ----------------------------------------------------
    def pick_char(self, pid, pk, cid):
        """Caller holds room.lock. Sit a saved character into a seat (menu only)."""
        g = self.game
        if g.state != "menu" or not KEY_RE.match(pk):
            return
        c = self.hub.saves.get(pk, cid)
        if not c:
            return
        other = g.players[1 - pid]
        if other.joined and other.char and other.char["id"] == cid and self.pks[1 - pid] == pk:
            return   # the same character cannot fill both seats
        view = self.hub.saves.view(c)
        pl = g.players[pid]
        pl.joined = True
        pl.ready = False
        pl.sel = CLASS_ORDER.index(c["cls"])
        pl.char = view
        pl.load_char()
        self.pks[pid] = pk

    def sync_char(self, pk, view):
        """A character changed in the menu (talent learned, respec): refresh the seat playing it."""
        g = self.game
        if g.state != "menu":
            return
        for i in (0, 1):
            pl = g.players[i]
            if self.pks[i] == pk and pl.char and pl.char["id"] == view["id"]:
                pl.char = view
                pl.load_char()

    def award_xp(self, p, xp, boss, clear, run):
        pk = self.pks[p.pid]
        if not pk or not p.char:
            return None
        return self.hub.saves.award(pk, p.char["id"], xp, boss=boss, clear=clear, run=run)

    def record_score(self, result):
        names = [self.names[p.pid] for p in self.game.joined()]
        self.hub.record_score(dict(result, names=names))


class Hub:
    def __init__(self):
        self.lock = threading.RLock()
        self.score_lock = threading.Lock()
        self.rooms = {}
        self.sessions = {}      # sid -> dict(room=code|None, name, seen, disc)
        self.mm_queue = []      # dicts: sid, name, seen
        self.matched = {}       # sid -> (code, seats)
        self.scores = self.load_scores()
        self.saves = SaveStore(SAVES)
        self.running = True

    # ---- scores --------------------------------------------------------
    def load_scores(self):
        try:
            with open(SCORES, "r") as f:
                data = json.load(f)
            return sorted(data, key=lambda s: -s.get("gold", 0))[:MAX_SCORES]
        except Exception:
            return []

    def record_score(self, result):
        entry = dict(gold=result["gold"], bosses=result["bosses"], won=result["won"], classes=result["classes"],
                     names=result.get("names") or [], date=time.strftime("%Y-%m-%d"), ts=int(time.time()))
        with self.score_lock:
            self.scores.append(entry)
            self.scores.sort(key=lambda s: -s.get("gold", 0))
            del self.scores[MAX_SCORES:]
            try:
                tmp = SCORES + ".tmp"
                with open(tmp, "w") as f:
                    json.dump(self.scores, f)
                os.replace(tmp, SCORES)
            except OSError:
                pass

    # ---- sessions ------------------------------------------------------
    def session(self, sid):
        s = self.sessions.get(sid)
        if not s:
            s = self.sessions[sid] = dict(room=None, name="", seen=time.monotonic(), disc=time.monotonic())
        s["seen"] = time.monotonic()
        return s

    def new_code(self):
        for _ in range(200):
            c = "".join(random.choice(CODE_ALPHA) for _ in range(4))
            if c not in self.rooms:
                return c
        return None

    def room_of(self, sid):
        s = self.sessions.get(sid)
        return self.rooms.get(s["room"]) if s and s["room"] else None

    def _drop_ticket(self, sid):
        self.mm_queue = [t for t in self.mm_queue if t["sid"] != sid]

    def _seat_in(self, room, sid, name, local=False):
        with room.lock:
            seats = room.sit(sid, name, local)
            if seats is None:
                return None
            room.empty_since = time.monotonic()
            names = list(room.names)
        s = self.session(sid)
        s["room"], s["name"], s["disc"] = room.code, name, time.monotonic()
        return seats, names

    def leave(self, sid):
        with self.lock:
            self._drop_ticket(sid)
            self.matched.pop(sid, None)
            room = self.room_of(sid)
            s = self.sessions.get(sid)
            if s:
                s["room"] = None
            if not room:
                return
            with room.lock:
                seats = room.my_seats(sid)
                name = room.names[seats[0]] if seats else ""
                moves = room.unsit(sid)
                for q, qs in list(room.clients.items()):
                    if qs == sid:
                        room.clients.pop(q, None)
                        try:
                            q.put_nowait(sse("kicked", {}))
                        except queue.Full:
                            pass
                for osid, seat in moves.items():
                    for q, qs in room.clients.items():
                        if qs == osid:
                            try:
                                q.put_nowait(sse("seat", dict(seats=[seat])))
                            except queue.Full:
                                pass
                if name:
                    room.add_chat(-1, "", "%s LEFT" % name, sys=True)
                empty = not room.sids()
            if empty:
                self.rooms.pop(room.code, None)

    # ---- lobby actions -------------------------------------------------
    def create(self, sid, name, local=False):
        with self.lock:
            self.leave(sid)
            if len(self.rooms) >= MAX_ROOMS:
                return dict(ok=False, error="SERVER BUSY, TRY AGAIN SOON")
            code = self.new_code()
            room = self.rooms[code] = Room(self, code)
            res = self._seat_in(room, sid, name, local)
        room.add_chat(-1, "", "%s CREATED THE GAME. CODE %s" % (name, code), sys=True)
        return dict(ok=True, code=code, seats=res[0], names=res[1])

    def join(self, sid, name, code):
        code = (code or "").strip().upper()
        with self.lock:
            room = self.rooms.get(code)
            if not room:
                return dict(ok=False, error="NO GAME WITH THAT CODE")
            if self.room_of(sid) is room and room.my_seats(sid):
                return dict(ok=True, code=code, seats=room.my_seats(sid), names=list(room.names))
            if room.game.state != "menu":
                return dict(ok=False, error="THAT RUN HAS ALREADY STARTED")
            if room.local or all(room.seats):
                return dict(ok=False, error="THAT GAME IS FULL")
            self.leave(sid)
            res = self._seat_in(room, sid, name)
            if res is None:
                return dict(ok=False, error="THAT GAME IS FULL")
        room.add_chat(-1, "", "%s JOINED" % name, sys=True)
        return dict(ok=True, code=code, seats=res[0], names=res[1])

    def match(self, sid, name):
        now = time.monotonic()
        with self.lock:
            self.leave(sid)
            self.session(sid)["name"] = name
            for t in list(self.mm_queue):
                if t["sid"] != sid and now - t["seen"] < MATCH_STALE:
                    self.mm_queue.remove(t)
                    code = self.new_code()
                    if not code:
                        return dict(ok=False, error="SERVER BUSY, TRY AGAIN SOON")
                    room = self.rooms[code] = Room(self, code)
                    a = self._seat_in(room, t["sid"], t["name"])
                    b = self._seat_in(room, sid, name)
                    self.matched[t["sid"]] = (code, a[0], b[1])
                    room.add_chat(-1, "", "MATCHED: %s AND %s" % (t["name"], name), sys=True)
                    return dict(ok=True, status="matched", code=code, seats=b[0], names=b[1])
            self.mm_queue.append(dict(sid=sid, name=name, seen=now))
            return dict(ok=True, status="waiting", waiting=len(self.mm_queue))

    def match_status(self, sid):
        with self.lock:
            m = self.matched.pop(sid, None)
            if m:
                return dict(ok=True, status="matched", code=m[0], seats=m[1], names=m[2])
            for t in self.mm_queue:
                if t["sid"] == sid:
                    t["seen"] = time.monotonic()
                    return dict(ok=True, status="waiting", waiting=len(self.mm_queue))
            return dict(ok=True, status="idle")

    def match_cancel(self, sid):
        with self.lock:
            self._drop_ticket(sid)
            self.matched.pop(sid, None)
        return dict(ok=True)

    # ---- characters ----------------------------------------------------
    def chars(self, sid, msg):
        pk = str(msg.get("pk") or "")
        if not KEY_RE.match(pk):
            return dict(ok=False, error="BAD PROFILE KEY")
        op = msg.get("op") or "list"
        st = self.saves
        err = ""
        cid = str(msg.get("id") or "")
        if op == "create":
            c, err = st.create(pk, msg.get("name"), msg.get("cls"))
        elif op == "delete":
            if not st.delete(pk, cid):
                err = "NO SUCH CHARACTER"
        elif op == "rename":
            if not st.rename(pk, cid, msg.get("name")):
                err = "COULD NOT RENAME"
        elif op in ("learn", "respec"):
            room = self.room_of(sid)
            if room and room.game.state != "menu":
                return dict(ok=False, error="TALENTS CHANGE BETWEEN RUNS")
            if op == "learn":
                c, err = st.learn(pk, cid, str(msg.get("talent") or ""))
            else:
                c = st.respec(pk, cid)
                if not c:
                    err = "NO SUCH CHARACTER"
            if c and room:
                with room.lock:
                    room.sync_char(pk, c)
        elif op != "list":
            return dict(ok=False, error="BAD OP")
        if err:
            return dict(ok=False, error=err, chars=st.list(pk))
        return dict(ok=True, chars=st.list(pk), max=__import__("saves").MAX_CHARS)

    def stats(self):
        with self.lock:
            now = time.monotonic()
            online = sum(len(r.sids()) for r in self.rooms.values())
            waiting = len([t for t in self.mm_queue if now - t["seen"] < MATCH_STALE])
            return dict(rooms=len(self.rooms), online=online, waiting=waiting)

    def chat(self, sid, text):
        text = clean_text(text)
        if not text:
            return dict(ok=False)
        room = self.room_of(sid)
        if not room:
            return dict(ok=False, error="NOT IN A GAME")
        now = time.monotonic()
        with room.lock:
            seats = room.my_seats(sid)
            if not seats:
                return dict(ok=False)
            if now - room.last_chat.get(sid, 0) < 0.6:
                return dict(ok=False, error="SLOW DOWN")
            room.last_chat[sid] = now
            seat, name = seats[0], room.names[seats[0]]
        room.add_chat(seat, name, text)
        return dict(ok=True)

    def input(self, sid, msg):
        room = self.room_of(sid)
        if room:
            room.apply(sid, msg)
        s = self.sessions.get(sid)
        if s:
            s["seen"] = time.monotonic()
        return dict(ok=True, in_room=bool(room))

    # ---- streaming -----------------------------------------------------
    def attach(self, sid, code):
        with self.lock:
            room = self.room_of(sid)
            if not room or room.code != (code or "").upper() or not room.my_seats(sid):
                return None, None
            q = queue.Queue(maxsize=6)
            with room.lock:
                room.clients[q] = sid
                self.sessions[sid]["disc"] = None
                room.empty_since = None
                q.put_nowait(sse("seat", dict(seats=room.my_seats(sid))))
                for m in room.chat[-30:]:
                    q.put_nowait(sse("chat", m))
            return room, q

    def detach(self, room, q):
        with room.lock:
            sid = room.clients.pop(q, None)
            if sid and sid not in room.clients.values():
                s = self.sessions.get(sid)
                if s:
                    s["disc"] = time.monotonic()
            if not room.clients:
                room.empty_since = time.monotonic()

    # ---- loop ----------------------------------------------------------
    def loop(self):
        dt = 1.0 / TICK_RATE
        nxt = time.perf_counter()
        last_maint = 0.0
        while self.running:
            nxt += dt
            for room in list(self.rooms.values()):
                room.step()
            now = time.monotonic()
            if now - last_maint > 1.0:
                last_maint = now
                try:
                    self.maintain(now)
                except Exception as ex:
                    print("maintenance error:", repr(ex))
            sleep = nxt - time.perf_counter()
            if sleep > 0:
                time.sleep(sleep)
            else:
                nxt = time.perf_counter()

    def maintain(self, now):
        with self.lock:
            self.mm_queue = [t for t in self.mm_queue if now - t["seen"] < MATCH_STALE]
            for sid, s in list(self.sessions.items()):
                if s["room"] and s["disc"] and now - s["disc"] > GRACE:
                    self.leave(sid)
                elif not s["room"] and now - s["seen"] > 600:
                    self.sessions.pop(sid, None)
            for code, room in list(self.rooms.items()):
                if room.empty_since and now - room.empty_since > EMPTY_ROOM_TTL:
                    self.rooms.pop(code, None)
                else:
                    room.check_hold()


