    if path == "/api/meta":
        return 200, meta()
    if path in ("/api/leaderboard", "/api/scores"):
        with HUB.score_lock:
            return 200, HUB.scores[:100]
    if path == "/api/lobby":
        return 200, HUB.stats()
    if path == "/api/match/status":
        sid = q1("sid")
        return 200, (HUB.match_status(sid) if SID_RE.match(sid) else dict(ok=False))
    return None


def api_post(path, msg):
    """JSON POST endpoints. Returns (status, object). Shared with the in-browser build."""
    sid = str(msg.get("sid") or "")
    if not SID_RE.match(sid):
        return 400, dict(ok=False, error="BAD SESSION")
    name = clean_name(msg.get("name"))
    if path in ("/api/create", "/api/join", "/api/match") and not name:
        return 200, dict(ok=False, error="ENTER A NAME FIRST")
    if path == "/api/input":
        return 200, HUB.input(sid, msg)
    if path == "/api/create":
        return 200, HUB.create(sid, name, bool(msg.get("local")))
    if path == "/api/join":
        return 200, HUB.join(sid, name, str(msg.get("code") or ""))
    if path == "/api/match":
        return 200, HUB.match(sid, name)
    if path == "/api/match/cancel":
        return 200, HUB.match_cancel(sid)
    if path == "/api/chars":
        return 200, HUB.chars(sid, msg)
    if path == "/api/leave":
        HUB.leave(sid)
        return 200, dict(ok=True)
    if path == "/api/chat":
        return 200, HUB.chat(sid, msg.get("text"))
    return 404, dict(error="not found")


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    timeout = 15   # a stalled client (backgrounded phone, dead wifi) frees its thread instead of hanging

    def log_message(self, fmt, *args):
        pass

    def _send(self, code, body, ctype="application/json", extra=None):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.cors()
        for k, v in (extra or {}).items():
            self.send_header(k, v)
        self.end_headers()
        self.wfile.write(body)

    def cors(self):
        if CORS_ORIGIN:
            self.send_header("Access-Control-Allow-Origin", CORS_ORIGIN)
            self.send_header("Vary", "Origin")

    def do_OPTIONS(self):
        self.send_response(204)
        self.cors()
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.send_header("Access-Control-Max-Age", "86400")
        self.send_header("Content-Length", "0")
        self.end_headers()

    def _json(self, obj, code=200):
        self._send(code, json.dumps(obj, separators=(",", ":")).encode())

    def do_GET(self):
        u = urlparse(self.path)
        path, qs = u.path, parse_qs(u.query)
        q1 = lambda k: (qs.get(k) or [""])[0]
        if path == "/api/stream":
            return self.stream(q1("sid"), q1("room"))
        r = api_get(path, qs)
        if r:
            return self._json(r[1], r[0])
        if path == "/":
            path = "/index.html"
        fp = os.path.normpath(os.path.join(STATIC, path.lstrip("/")))
        if not fp.startswith(STATIC) or not os.path.isfile(fp):
            return self._send(404, b'{"error":"not found"}')
        with open(fp, "rb") as f:
            body = f.read()
        self._send(200, body, MIME.get(os.path.splitext(fp)[1], "application/octet-stream"))

    def do_POST(self):
        path = urlparse(self.path).path
        try:
            n = int(self.headers.get("Content-Length", "0"))
            if n > 20000:
                self.close_connection = True
                return self._send(413, b"{}", extra={"Connection": "close"})
            msg = json.loads(self.rfile.read(n) or b"{}")
            if not isinstance(msg, dict):
                raise ValueError
        except Exception:
            return self._send(400, b'{"error":"bad json"}')
        code, obj = api_post(path, msg)
        self._json(obj, code)

    def stream(self, sid, code):
        if not SID_RE.match(sid):
            return self._send(400, b"{}")
        room, q = HUB.attach(sid, code)
        if not room:
            return self._send(410, b'{"error":"gone"}')
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Connection", "keep-alive")
        self.send_header("X-Accel-Buffering", "no")
        self.cors()
        self.end_headers()
        try:
            while True:
                try:
                    data = q.get(timeout=5)
                except queue.Empty:
                    data = b": keepalive\n\n"
                self.wfile.write(data)
                self.wfile.flush()
                if data.startswith(b"event: kicked"):
                    break
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError, OSError):
            pass
        finally:
            HUB.detach(room, q)
            self.close_connection = True


class Server(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True


def lan_ip():
    try:
        sk = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sk.connect(("10.255.255.255", 1))   # no packet is sent; this just picks the outgoing interface
        ip = sk.getsockname()[0]
        sk.close()
        return ip
    except OSError:
        return None


def main():
    ap = argparse.ArgumentParser(description="WARCRAFT: ATARI - an unofficial fan game")
    ap.add_argument("--host", default="127.0.0.1", help="use 0.0.0.0 so other devices can connect")
    ap.add_argument("--port", type=int, default=int(os.environ.get("PORT", "8000")), help="default: $PORT or 8000")
    ap.add_argument("--cors", default=os.environ.get("NAXX_CORS", ""), help="allow this website to use the API, e.g. https://you.github.io")
    args = ap.parse_args()
    global CORS_ORIGIN
    CORS_ORIGIN = args.cors.strip().rstrip("/")
    t = threading.Thread(target=HUB.loop, daemon=True)
    t.start()
    srv = Server((args.host, args.port), Handler)
    print("WARCRAFT: ATARI (unofficial fan game, not affiliated with Blizzard) running at http://%s:%d" % ("localhost" if args.host in ("127.0.0.1", "0.0.0.0") else args.host, args.port))
    if args.host in ("0.0.0.0", ""):
        ip = lan_ip()
        if ip:
            print("On a phone or another device on the same wifi, open http://%s:%d" % (ip, args.port))
    else:
        print("Tip: start with --host 0.0.0.0 to play from a phone or let friends on your network join.")
    print("Ctrl+C to quit.")
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        HUB.running = False
        srv.server_close()


if __name__ == "__main__":
    main()

spells.py:
"""Player spell implementations. Each spell is fn(g, p, spell) -> True | 'free' | False."""

import math

from util import clamp, hyp, norm, in_cone
from data import RESOURCES

NO_CHARGE = {"whirlwind", "enrage"}          # need a minimum, but do not spend it up front
NO_WINDFURY = {"whirlwind", "charge", "deathgrip", "felrush", "metamorphosis", "fortifyingbrew", "spinningcrane", "eyebeam", "explosivetrap", "freezetrap", "consecration",
               "deathanddecay", "bearform", "stealth", "divineshield"}


# ---------------------------------------------------------------- helpers
def fx_nova(g, p, r, color):
    g.ev(t="fx", k="nova", x=round(p.x, 1), y=round(p.y, 1), r=r, c=color)


def fire(g, p, target, speed, dmg, elem, color, kind="bolt", r=2.5, life=2.2, **kw):
    if target is not None:
        dx, dy = norm(target.x - p.x, target.y - p.y)
        p.fx, p.fy = dx, dy
    else:
        dx, dy = p.fx, p.fy
    pr = dict(id=g.nid(), team="player", x=p.x + dx * 4, y=p.y + dy * 4, vx=dx * speed, vy=dy * speed, r=r,
              dmg=dmg, elem=elem, life=life, src=p, kind=kind, color=color, pierce=False, hit=set(), sid=g.ctx_sid)
    pr.update(kw)
    g.projs.append(pr)
    return pr


def cone_targets(g, p, length, half_deg):
    half = math.radians(half_deg)
    out = []
    for e in g.enemies:
        if e.alive and in_cone(p.x, p.y, p.fx, p.fy, e.x, e.y, e.r, length, half):
            out.append(e)
    out.sort(key=lambda e: hyp(e.x - p.x, e.y - p.y))
    return out


def line_targets(g, p, length, half_w):
    """Enemies inside a rectangle starting at the player and running `length` along the facing."""
    out = []
    for e in g.enemies:
        if not e.alive:
            continue
        rx, ry = e.x - p.x, e.y - p.y
        along = rx * p.fx + ry * p.fy
        across = abs(-rx * p.fy + ry * p.fx)
        if -e.r <= along <= length + e.r and across <= half_w + e.r:
            out.append(e)
    return out


def face_nearest(g, p, maxd=60):
    e = g.nearest_enemy(p, maxd)
    if e:
        p.fx, p.fy = norm(e.x - p.x, e.y - p.y)
    return e


def allies(g):
    return [a for a in g.players if a.joined and a.alive]


def party_buff(g, name, dur, val):
    for a in allies(g):
        a.add_status(name, dur, val)
        g.text(a.x, a.y - 10, name.upper(), "#ffff55")


def leave_stealth(g, p):
    if p.form == "stealth":
        p.clear_status("stealth")
        p.form = None
        p.cd["stealth"] = max(p.cd.get("stealth", 0.0), 6.0)


def dash(g, p, dx, dy, dist_px):
    steps = int(dist_px // 3)
    for _ in range(steps):
        nx, ny = p.x + dx * 3, p.y + dy * 3
        if g.blocked(nx, ny, p.r):
            break
        p.x, p.y = nx, ny
    g.constrain(p)
    g.ev(t="fx", k="nova", x=round(p.x, 1), y=round(p.y, 1), r=8, c="#ffffff")


# ---------------------------------------------------------------- casting
def cast(g, p, idx):
    lst = p.spell_list()
    if idx >= len(lst):
        return
    sp = lst[idx]
    sid = sp["id"]
    # toggles that can always be cancelled
    if sid == "whirlwind" and p.has("whirl"):
        p.clear_status("whirl")
        return
    if sid == "enrage" and p.has("enrage"):
        p.clear_status("enrage")
        return
    if sid == "stealth" and p.form == "stealth":
        leave_stealth(g, p)
        return
    if sid == "bearform" and p.form == "bear":
        exit_bear(g, p)
        p.cd["bearform"] = 3.0
        return
    if p.gcd > 0 or p.cd.get(sid, 0.0) > 0:
        return
    need = p.spell_cost(sp)
    if p.res < need - 1e-9:
        g.text(p.x, p.y - 10, "NO " + RESOURCES[p.rtype]["label"], RESOURCES[p.rtype]["color"])
        return
    g.ctx_sid = sid
    try:
        ok = SPELLS[sid](g, p, sp)
    finally:
        g.ctx_sid = None
    if not ok:
        g.text(p.x, p.y - 10, "NO TARGET", "#aaaaaa")
        return
    if sid not in NO_CHARGE:
        p.res = max(0.0, p.res - need)
    p.cd[sid] = p.spell_cd(sp)
    p.gcd = 0.25
    g.sfx("cast")
    if (sp["kind"] in ("dmg", "heal") and sid not in NO_WINDFURY and p.has("windfury")
            and g.rng.random() < p.sval("windfury", 0.25)):
        g.text(p.x, p.y - 14, "WINDFURY!", "#55ffff")

        def again(g=g, p=p, sp=sp, fn=SPELLS[sid]):
            if p.alive:
                fn(g, p, sp)   # later() restores the spell context for the talent bonuses
        g.later(0.28, again)


def auto_attack(g, p):
    if not (p.cdef["melee"] or p.form == "bear"):
        return
    if p.form == "stealth" or p.swing > 0:
        return
    e = g.nearest_enemy(p, 13)
    if not e:
        return
    p.swing = 0.9
    p.fx, p.fy = norm(e.x - p.x, e.y - p.y)
    g.hit_enemy(e, 6 if p.form == "bear" else 7, p, "phys")
    p.gain(6)
    g.ev(t="fx", k="slash", x=round(e.x, 1), y=round(e.y, 1), r=5, c="#ffffff")


def player_ongoing(g, p, dt):
    if p.pet_t > 0:
        p.pet_t -= dt
        if p.pet is not None:
            update_pet(g, p, dt)
        if p.pet_t <= 0:
            p.pet = None
            p.pet_t = 0.0
            g.text(p.x, p.y - 14, "FALCON LEAVES", "#aa5500")
    if p.has("unholyls"):
        p.leech_t -= dt
        if p.leech_t <= 0:
            p.leech_t = 1.0
            if p.leech_acc >= 1.0:
                g.text(p.x, p.y - 12, "+%d" % int(p.leech_acc), "#55ff55")
            p.leech_acc = 0.0
    if p.has("whirl"):
        p.res -= 10.0 * dt
        p.whirl_t -= dt
        if p.whirl_t <= 0:
            p.whirl_t += 0.5
            fx_nova(g, p, 32, "#ffffff")
            for e in g.enemies_near(p.x, p.y, 32):
                g.hit_enemy(e, 10, p, "phys")
            g.sfx("hit")
        if p.res <= 0:
            p.res = 0.0
            p.clear_status("whirl")
    if p.has("enrage"):
        p.res -= 10.0 * dt
        g.heal(p, 4.0 * dt, p, quiet=True)
        if p.res <= 0:
            p.res = 0.0
            p.clear_status("enrage")


