def mortalstrike(g, p, sp):
    es = cone_targets(g, p, 26, 55)
    if not es:
        e = face_nearest(g, p, 26)
        if not e:
            return False
        es = [e]
    for e in es:
        g.hit_enemy(e, 26, p, "phys")
        g.ev(t="fx", k="slash", x=round(e.x, 1), y=round(e.y, 1), r=7, c="#ff5555")
