    dx, dy = norm(e.x - p.x, e.y - p.y)
    gap = e.r + p.r + 2
    tx, ty = e.x - dx * gap, e.y - dy * gap
    p.fx, p.fy = dx, dy
    p.x, p.y = tx, ty
    g.constrain(p)
    g.ev(t="fx", k="nova", x=round(p.x, 1), y=round(p.y, 1), r=10, c="#ffffff")
