def update_pet(g, p, dt):
    """The hunter's falcon: orbits its owner, dives at the nearest enemy, returns."""
    pet = p.pet
    pet["cd"] -= dt
    pet["ang"] += dt * 2.6

    def go(tx, ty, speed):
        dx, dy = tx - pet["x"], ty - pet["y"]
        d = hyp(dx, dy)
        if d < 1e-6:
            return 0.0
        k = min(1.0, speed * dt / d)
        pet["x"] += dx * k
        pet["y"] += dy * k
        return d - speed * dt

    if pet["st"] == "orbit":
        go(p.x + math.cos(pet["ang"]) * 15, p.y - 12 + math.sin(pet["ang"]) * 7, 140)
        if pet["cd"] <= 0:
            tgt, bd = None, 150.0
            for e in g.enemies:
                if e.alive and not e.gated:
                    d = hyp(e.x - p.x, e.y - p.y)
                    if d < bd:
                        tgt, bd = e, d
            if tgt is not None:
                pet["tgt"] = tgt
                pet["st"] = "dive"
    elif pet["st"] == "dive":
        tgt = pet["tgt"]
        if tgt is None or not tgt.alive:
            pet["st"] = "return"
            return
        left = go(tgt.x, tgt.y, 170)
        if hyp(tgt.x - pet["x"], tgt.y - pet["y"]) <= tgt.r + 3:
            g.hit_enemy(tgt, 10, p, "phys")
            g.ev(t="fx", k="slash", x=round(tgt.x, 1), y=round(tgt.y, 1), r=5, c="#aa5500")
            pet["cd"] = 1.4
            pet["st"] = "return"
    else:
        go(p.x, p.y - 12, 160)
        if hyp(p.x - pet["x"], p.y - 12 - pet["y"]) < 10:
            pet["st"] = "orbit"


