"""Small math helpers shared by the engine, spells and boss scripts."""

import math


def clamp(v, lo, hi):
    return lo if v < lo else hi if v > hi else v


def hyp(dx, dy):
    return math.hypot(dx, dy)


def norm(dx, dy, default=(0.0, 1.0)):
    d = math.hypot(dx, dy)
    if d < 1e-6:
        return default
    return dx / d, dy / d


def dist(a, b):
    return math.hypot(a.x - b.x, a.y - b.y)


def in_cone(ox, oy, fx, fy, tx, ty, tr, length, half):
    """Is a circle at (tx,ty) radius tr inside a cone from (ox,oy) facing (fx,fy)?"""
    dx, dy = tx - ox, ty - oy
    d = math.hypot(dx, dy)
    if d > length + tr:
        return False
    if d < 1e-6 or d <= tr + 3:
        return True
    cosang = clamp((fx * dx + fy * dy) / d, -1.0, 1.0)
    ang = math.acos(cosang)
    return ang <= half + math.atan2(tr, d)


def seg_dist(px, py, ax, ay, bx, by):
    """Distance from point p to segment ab."""
    abx, aby = bx - ax, by - ay
    l2 = abx * abx + aby * aby
    if l2 < 1e-9:
        return math.hypot(px - ax, py - ay)
    t = clamp(((px - ax) * abx + (py - ay) * aby) / l2, 0.0, 1.0)
    return math.hypot(px - (ax + t * abx), py - (ay + t * aby))


def circle_rect_push(cx, cy, cr, rx, ry, rw, rh):
    """If the circle overlaps the rect, return the corrected centre, else None."""
    nx = clamp(cx, rx, rx + rw)
    ny = clamp(cy, ry, ry + rh)
    dx, dy = cx - nx, cy - ny
    d2 = dx * dx + dy * dy
    if d2 >= cr * cr:
        return None
    if d2 > 1e-9:
        d = math.sqrt(d2)
        k = (cr - d) / d
        return cx + dx * k, cy + dy * k
    # centre is inside the rect: push out through the nearest edge
    left, right = cx - rx, rx + rw - cx
    top, bot = cy - ry, ry + rh - cy
    m = min(left, right, top, bot)
    if m == left:
        return rx - cr, cy
    if m == right:
        return rx + rw + cr, cy
    if m == top:
        return cx, ry - cr
    return cx, ry + rh + cr

host.py:
"""Glue that runs the real game server logic (server.py's Hub) inside the browser (Pyodide, in a Web Worker).
No threads or sockets: the worker calls tick() ~30 times a second and handle() for every API request."""
import json
import os
import queue
import sys
import urllib.parse

sys.path.insert(0, "/app")
os.chdir("/app")
import server  # noqa: E402  (creates server.HUB, reads /app/saves.json and /app/scores.json if present)

HUB = server.HUB
STREAMS = {}                      # sid -> (room, queue)
_seen = {}                        # file -> mtime_ns, to report saves/scores changes back to the page
FILES = ("saves.json", "scores.json")


def handle(method, url, body):
    u = urllib.parse.urlparse(url)
    path, qs = u.path, urllib.parse.parse_qs(u.query)
    if method == "GET":
        if path == "/api/stream":
            sid, code = (qs.get("sid") or [""])[0], (qs.get("room") or [""])[0]
            if not server.SID_RE.match(sid):
                return json.dumps(dict(status=400, body={}))
            old = STREAMS.pop(sid, None)
            if old:
                HUB.detach(*old)
            room, q = HUB.attach(sid, code)
            if not room:
                return json.dumps(dict(status=410, body=dict(error="gone")))
            STREAMS[sid] = (room, q)
            return json.dumps(dict(status=200, body={}))
        r = server.api_get(path, qs)
        if r:
            return json.dumps(dict(status=r[0], body=r[1]))
        return json.dumps(dict(status=404, body=dict(error="not found")))
    try:
        msg = json.loads(body or "{}")
        if not isinstance(msg, dict):
            raise ValueError
    except Exception:
        return json.dumps(dict(status=400, body=dict(error="bad json")))
    code, obj = server.api_post(path, msg)
    return json.dumps(dict(status=code, body=obj))


def close_stream(sid):
    old = STREAMS.pop(sid, None)
    if old:
        HUB.detach(*old)


def tick():
    """Advance every room one step and return the pending server-sent-event frames as one string."""
    for room in list(HUB.rooms.values()):
        room.step()
    out = []
    for sid, (room, q) in list(STREAMS.items()):
        while True:
            try:
                out.append(q.get_nowait().decode("utf-8"))
            except queue.Empty:
                break
    return "".join(out)


def changed_files():
    """{filename: content} for saves/scores files written since the last call."""
    res = {}
    for name in FILES:
        try:
            m = os.stat(os.path.join("/app", name)).st_mtime_ns
        except OSError:
            continue
        if _seen.get(name) != m:
            _seen[name] = m
            with open(os.path.join("/app", name)) as f:
                res[name] = f.read()
    return json.dumps(res) if res else ""


def maintain():
    import time
    HUB.maintain(time.monotonic())
